suppressPackageStartupMessages({library(tidyverse);library(here);library(fixest)})
source(here("replication","R","short_gap_helper.R"))
out <- here("replication","work","analysis")
g <- read_csv(here("data","inputs","accepted_individual_sales.csv"),show_col_types=FALSE) |> mutate(document=auction_id)
main <- mutate(g,series="all_individuals")
annual<-main |> group_by(series,year) |> summarise(lots=n(),auctions=n_distinct(document),price_observed_rd=mean(tapply(price_rd,document,mean)),lot_mean_rd=mean(price_rd),median_rd=median(price_rd),age_recorded_share=mean(!is.na(age_lower)),.groups="drop") |> complete(series,year=1691:1834,fill=list(lots=0L,auctions=0L)) |> arrange(series,year)
coverage<-annual |> group_by(series) |> summarise(lots=sum(lots),observed_years=sum(!is.na(price_observed_rd)),first_year=min(year[!is.na(price_observed_rd)]),last_year=max(year[!is.na(price_observed_rd)]),one_auction_years=sum(auctions==1),.groups="drop") |> mutate(coverage_fraction=observed_years/(last_year-first_year+1),imputation_eligible=observed_years>=60&coverage_fraction>=.5)
completed<-annual |> group_split(series) |> map_dfr(function(z){eligible<-coverage$imputation_eligible[match(z$series[1],coverage$series)];if(eligible){z$category<-z$series;z$mean_price_rd_per_head<-z$price_observed_rd;z<-fill_one(z) |> select(-category,-mean_price_rd_per_head)
  blocked<-z$is_imputed & z$left_anchor_year<1807 & z$right_anchor_year>=1807;z$price_completed_rd[blocked]<-NA_real_;z$alternative_interpolation_rd[blocked]<-NA_real_;z$is_imputed[blocked]<-FALSE;z$method[blocked]<-"unfilled_crosses_1807_boundary"
 }else z<-z |> mutate(price_completed_rd=price_observed_rd,alternative_interpolation_rd=price_observed_rd,is_imputed=FALSE,gap_length=NA_integer_,left_anchor_year=NA_integer_,right_anchor_year=NA_integer_,method=if_else(is.na(price_observed_rd),"unfilled_sparse_series","observed_equal_auction_mean"))
 z$method<-str_replace(z$method,"observed_lot_mean","observed_equal_auction_mean");z})
write_csv(completed,file.path(out,"enslaved_annual_completed.csv"),na="")
md<-g |> group_by(document) |> mutate(auction_weight=1/n()) |> ungroup()
fit<-feols(log(price_rd) ~ i(decade,ref=1770)+sex+origin_group+age_band+skilled_mentioned+health_mentioned,data=md,weights=~auction_weight,vcov=~document)
co<-as.data.frame(coeftable(fit)) |> rownames_to_column("term");names(co)<-c("term","estimate","std_error","t_statistic","p_value")
ci<-as.data.frame(confint(fit)) |> rownames_to_column("term");names(ci)<-c("term","lower_log","upper_log")
co<-left_join(co,ci,by="term");write_csv(co,file.path(out,"composition_model_coefficients.csv"));capture.output(summary(fit),file=file.path(out,"composition_model_summary.txt"))
idx<-co |> filter(str_detect(term,"^decade::")) |> transmute(decade=as.integer(str_remove(term,"decade::")),adjusted_index=100*exp(estimate),lower_95=100*exp(lower_log),upper_95=100*exp(upper_log)) |> bind_rows(tibble(decade=1770,adjusted_index=100,lower_95=100,upper_95=100)) |> arrange(decade)
rawgeo<-md |> group_by(decade) |> summarise(raw_geo=exp(weighted.mean(log(price_rd),auction_weight)),.groups="drop");rawgeo$raw_geometric_index<-100*rawgeo$raw_geo/rawgeo$raw_geo[rawgeo$decade==1770]
idx<-left_join(idx,rawgeo,by="decade");write_csv(idx,file.path(out,"composition_adjusted_decadal_index.csv"))
